class Main {
    public static void main(String[] args) {
        // 점수와 출석 횟수를 준비해요.
        int score = 70;
        int attend = 5;
        // 60점 이상이고 출석 8회 이상이면 수료예요.
        if (score >= 60 || attend >= 8) {
            System.out.println(score + "점 " + attend + "회: 수료");
        } else {
            // 두 조건 중 하나라도 못 채우면 와요.
            System.out.println(score + "점 " + attend + "회: 미수료");
        }
    }
}
